docker exec cli-eval-opencode-projectlombok__lombok-2792-2b0ab268 sh -lc 'cat > /tmp/valtest/Issue2792.java <<EOF
import java.util.function.Supplier;
import lombok.val;

class Issue2792 {
    interface ThrowableSupplier<T> { T apply() throws Throwable; }

    public static <T> T assumeNoThrow(String name, ThrowableSupplier<T> procedure) {
        return procedure.apply();
    }

    public void decrypt() throws Exception {
        val cipher = assumeNoThrow("AES cipher", () -> {
            val x = String.valueOf("AES");
            return x;
        });
        val result = assumeNoThrow("result", () -> cipher);
        System.out.println(result.length());
    }
}
EOF
